SELECT COUNT(*) FROM users as u, comments as c, votes as v, badges as b WHERE c.UserId = u.Id AND v.UserId = u.Id AND b.UserId = u.Id AND u.DownVotes<=11 AND u.CreationDate>='2010-07-31 17:32:56'::timestamp AND u.CreationDate<='2014-09-07 16:06:26'::timestamp AND c.Score=1 AND v.BountyAmount<=50 AND b.Date<='2014-08-25 19:05:46'::timestamp;